int bcm63xx_soc_platform_probe ( struct platform_device * pdev , struct bcm_i2s_priv * i2s_priv ) { int ret ; ret = platform_get_irq ( pdev , 0 ) ; ret = devm_request_irq ( & pdev -> dev , ret , i2s_dma_isr , irq_get_trigger_type ( ret ) , "i2s_dma" , ( void * ) i2s_priv ) ; if ( ret ) { dev_err ( & pdev -> dev , "i2s_init: failed to request interrupt.ret=%d\n" , ret ) ; return ret ; } return devm_snd_soc_register_component ( & pdev -> dev , & bcm63xx_soc_platform , NULL , 0 ) ; } 